def install_qt_translations(app):
    """Localize standard Qt buttons and print dialogs as well as our own UI."""
    import sys
    from pathlib import Path
    from PySide6.QtCore import QTranslator,QLibraryInfo
    previous=getattr(app,'qt_translation',None)
    if previous:app.removeTranslator(previous)
    if LANGUAGE=='de':
        translator=QTranslator(app);path=(Path(sys._MEIPASS)/'translations'/'qtbase_de.qm') if getattr(sys,'frozen',False) else Path(QLibraryInfo.path(QLibraryInfo.TranslationsPath))/'qtbase_de.qm'
        if translator.load(str(path)):app.installTranslator(translator);app.qt_translation=translator

